for i, lang in ((1, 'en'), (2, 'es')):
    d = {'pages': {}, 'js': {}, 'api': {}}
    for sec, rows in (('pages', PAGES), ('js', JS), ('api', API)):
        for r in rows:
            d[sec][r[0]] = r[i]
    with open(os.path.join(ROOT, 'i18n', f'{lang}.json'), 'w', encoding='utf-8') as f:
        json.dump(d, f, ensure_ascii=False, indent=1, sort_keys=True)
    print(lang, {k: len(v) for k, v in d.items()})
